$verified = $false
$verifyError = $null
try {
  $sums = Invoke-RestMethod "$base/checksums.txt" -Headers @{ 'Accept' = 'text/plain'; 'User-Agent' = 'podcli-install' }
  $want = $sums -split "`n" |
    Where-Object { $_ -match ([regex]::Escape($asset) + '\s*$') } |
    ForEach-Object { ($_ -split '\s+')[0] } | Select-Object -First 1
  if (-not $want) {
    $verifyError = "no checksum entry for $asset"
  } else {
    $got = (Get-FileHash $dest -Algorithm SHA256).Hash.ToLower()
    if ($got -ne $want.ToLower()) { $verifyError = "checksum mismatch (got $got want $want)" } else { $verified = $true }
  }
} catch {
  $verifyError = "could not fetch checksums.txt: $($_.Exception.Message)"
}
if (-not $verified) {
  Remove-Item $dest -Force -ErrorAction SilentlyContinue
  throw "refusing to install an unverified binary: $verifyError"
}
Write-Host "  checksum verified"

